const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000/api';

export const fetchApi = async (endpoint, options = {}) => {
  const response = await fetch(`${API_URL}${endpoint}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });
  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Unknown error' }));
    throw new Error(error.error || 'API request failed');
  }
  return response.json();
};

export const getProfiles = () => fetchApi('/profiles');
export const getGroups = () => fetchApi('/groups');
export const getPosts = (query = '') => fetchApi(`/posts${query ? `?${query}` : ''}`);
export const getMessages = () => fetchApi('/messages');
export const getNotifications = () => fetchApi('/notifications');

export const createPost = (data) => fetchApi('/posts', { method: 'POST', body: JSON.stringify(data) });
export const deletePost = (id) => fetchApi(`/posts/${id}`, { method: 'DELETE' });

import React from 'react';
