import React from 'react';
import { NavLink } from 'react-router-dom';
import { Home, Users, Users2, MessageSquare, Bell, Compass } from 'lucide-react';
import ThemeToggle from './ThemeToggle';

const links = [
  { to: '/', icon: Home, label: 'Feed' },
  { to: '/profiles', icon: Users, label: 'Profiles' },
  { to: '/groups', icon: Users2, label: 'Groups' },
  { to: '/posts', icon: Compass, label: 'All Posts' },
  { to: '/messages', icon: MessageSquare, label: 'Messages' },
  { to: '/notifications', icon: Bell, label: 'Notifications' },
];

export default function Sidebar({ theme, toggleTheme }) {
  return (
    <aside className='w-64 bg-white dark:bg-gray-900 border-r border-gray-100 dark:border-gray-800 h-screen sticky top-0 hidden md:flex flex-col p-4'>
      <div className='flex items-center gap-2 px-3 py-4 mb-4'>
        <div className='w-8 h-8 rounded-lg bg-softGreen-500 flex items-center justify-center'>
          <Compass className='text-white' size={20} />
        </div>
        <h1 className='text-xl font-bold text-gray-800 dark:text-gray-100'>SocialApp</h1>
      </div>

      <div className='px-3 mb-4'>
        <ThemeToggle theme={theme} toggleTheme={toggleTheme} className='w-full' />
      </div>

      <nav className='flex-1 space-y-1'>
        {links.map(({ to, icon: Icon, label }) => (
          <NavLink
            key={to}
            to={to}
            className={({ isActive }) =>
              `flex items-center gap-3 px-4 py-3 rounded-lg font-medium transition-colors ${
                isActive
                  ? 'bg-softBlue-50 text-softBlue-600 dark:bg-softBlue-500/10 dark:text-softBlue-300'
                  : 'text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800 hover:text-gray-900 dark:hover:text-white'
              }`
            }
          >
            <Icon size={20} />
            <span>{label}</span>
          </NavLink>
        ))}
      </nav>

      <div className='mt-auto p-4 bg-softGreen-50 dark:bg-softGreen-500/10 rounded-xl text-softGreen-800 dark:text-softGreen-300 text-sm'>
        <p className='font-semibold mb-1'>Guest Mode</p>
        <p className='text-xs opacity-80'>Exploring without authentication. Actions are disabled.</p>
      </div>
    </aside>
  );
}

import React from 'react';
import { Sun, Moon } from 'lucide-react';

export default function ThemeToggle({ theme, toggleTheme, className = '' }) {
  return (
    <button
      type='button'
      onClick={toggleTheme}
      aria-label='Toggle theme'
      className={`flex items-center justify-between gap-2 px-3 py-2 rounded-lg border border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-gray-800/60 text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors ${className}`}
    >
      <span className='text-sm font-medium'>{theme === 'dark' ? 'Dark mode' : 'Light mode'}</span>
      {theme === 'dark' ? <Moon size={18} className='text-softBlue-300' /> : <Sun size={18} className='text-softGreen-600' />}
    </button>
  );
}

import React from 'react';
import { User } from 'lucide-react';

export default function ProfileCard({ profile }) {
  return (
