      <div className='w-16 h-16 rounded-full bg-softBlue-100 dark:bg-softBlue-500/10 flex items-center justify-center text-softBlue-500 dark:text-softBlue-300 mb-3'>
        {profile.avatar_url ? (
          <img src={profile.avatar_url} alt={profile.username} className='w-full h-full rounded-full object-cover' />
        ) : (
          <User size={32} />
        )}
      </div>
      <h3 className='font-bold text-gray-800 dark:text-gray-100'>{profile.display_name || profile.username}</h3>
      <p className='text-sm text-gray-500 dark:text-gray-400 mb-2'>@{profile.username}</p>
      {profile.bio && <p className='text-sm text-gray-600 dark:text-gray-300 italic mb-4'>{profile.bio}</p>}
      <button className='w-full py-2 px-4 bg-softGreen-50 dark:bg-softGreen-500/10 text-softGreen-700 dark:text-softGreen-300 rounded-lg font-medium hover:bg-softGreen-100 dark:hover:bg-softGreen-500/20 transition disabled:opacity-50' disabled>
        View Profile
