import React from 'react';
import { Mail } from 'lucide-react';

export default function MessageCard({ message }) {
  const isGroup = !!message.group_id;
  return (
    <div className='bg-white dark:bg-gray-900 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-800 flex items-start gap-3'>
      <div className={`p-2 rounded-lg ${isGroup ? 'bg-softBlue-50 text-softBlue-500 dark:bg-softBlue-500/10 dark:text-softBlue-300' : 'bg-softGreen-50 text-softGreen-500 dark:bg-softGreen-500/10 dark:text-softGreen-300'}`}>
        <Mail size={20} />
      </div>
      <div className='flex-1'>
        <div className='flex justify-between items-baseline mb-1'>
          <span className='font-semibold text-gray-800 dark:text-gray-100'>
            {isGroup ? 'Group Message' : 'Direct Message'}
          </span>
          <span className='text-xs text-gray-400 dark:text-gray-500'>{new Date(message.created_at).toLocaleString()}</span>
        </div>
        <p className='text-gray-700 dark:text-gray-300 text-sm'>{message.content}</p>
      </div>
    </div>
  );
}

import React from 'react';
import { Bell, MessageSquare, UserPlus, Heart } from 'lucide-react';

export default function NotificationCard({ notification }) {
  let Icon = Bell;
  let colorClass = 'bg-gray-50 text-gray-500 dark:bg-gray-800 dark:text-gray-300';

  if (notification.type.includes('comment')) {
    Icon = MessageSquare;
    colorClass = 'bg-softBlue-50 text-softBlue-500 dark:bg-softBlue-500/10 dark:text-softBlue-300';
  } else if (notification.type.includes('reaction') || notification.type.includes('like')) {
    Icon = Heart;
    colorClass = 'bg-softGreen-50 text-softGreen-500 dark:bg-softGreen-500/10 dark:text-softGreen-300';
  } else if (notification.type.includes('follow') || notification.type.includes('member')) {
    Icon = UserPlus;
    colorClass = 'bg-softBlue-50 text-softBlue-500 dark:bg-softBlue-500/10 dark:text-softBlue-300';
  }

  return (
    <div className={`p-4 rounded-xl shadow-sm border ${notification.read_at ? 'bg-white dark:bg-gray-900 border-gray-100 dark:border-gray-800' : 'bg-softBlue-50/30 dark:bg-softBlue-500/10 border-softBlue-100 dark:border-softBlue-500/20'} flex items-start gap-3`}>
      <div className={`p-2 rounded-lg ${colorClass}`}>
        <Icon size={20} />
      </div>
      <div className='flex-1'>
        <div className='flex justify-between items-baseline mb-1'>
          <span className='font-semibold text-gray-800 dark:text-gray-100 text-sm'>{notification.type.replace(/_/g, ' ')}</span>
          <span className='text-xs text-gray-400 dark:text-gray-500'>{new Date(notification.created_at).toLocaleString()}</span>
        </div>
        {notification.data?.preview && <p className='text-gray-600 dark:text-gray-300 text-sm'>{notification.data.preview}</p>}
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { getPosts } from '../api/client';
import PostCard from '../components/PostCard';

export default function Home() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getPosts('order=created_at.desc&limit=10')
      .then(setPosts)
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <div className='p-8 text-center text-softBlue-500 dark:text-softBlue-300'>Loading feed...</div>;

  return (
    <div className='p-6 max-w-3xl mx-auto'>
      <h1 className='text-2xl font-bold text-gray-800 dark:text-gray-100 mb-6'>Recent Activity</h1>
      <div className='space-y-4'>
        {posts.length === 0 ? (
          <p className='text-gray-500 dark:text-gray-400'>No posts yet.</p>
        ) : (
          posts.map(post => <PostCard key={post.id} post={post} />)
        )}
      </div>
    </div>
  );
}

